flow.chain:
fileScanDir = '../../adm';
fileScanPattern = {{0}};
fileScannerTo = '{"dir":"'+fileScanDir+'","pattern":"'+fileScanPattern+'"}';

codeParser = {{1}};

fileParserJavaVersion = 'JAVA_17';
fileParserTo = '{"javaVersion":"'+fileParserJavaVersion+'"}';

codeGeneratorBtl = {{2}};
codeGeneratorTarget = 'target/web';
codeGeneratorTo = '{"btl":"'+codeGeneratorBtl+'","target":"'+codeGeneratorTarget+'"}';

THEN(
    beetl,
    ITERATOR(fileScanner.data(fileScannerTo)).parallel(true).DO(THEN(
        fileParser.data(fileParserTo),
        codeParser,
        codeGenerator.data(codeGeneratorTo)
    ))
);
